sp_widget.client_script:
api.controller = function() {
    var c = this;
    c.selectedAccount = null;

    c.selectAccount = function(acct) {
        c.selectedAccount = acct;
    };

    c.clearSelection = function() {
        c.selectedAccount = null;
    };
};

sp_widget.css:
.my-accounts-container {
    .panel-heading {
        background-color: #1a3a5c;
        color: #ffffff;
        .panel-title {
            font-size: 16px;
            font-weight: 600;
        }
    }
    .table > tbody > tr {
        cursor: pointer;
        &:hover { background-color: #f0f5fa; }
        &.selected-row {
            background-color: #d6e9f8;
            border-left: 3px solid #1a3a5c;
        }
    }
    .account-detail-panel {
        background: #f9fbfd;
        border: 1px solid #dce4ec;
        border-radius: 4px;
        padding: 20px;
        margin-top: 15px;
        .detail-header {
            font-size: 15px;
            font-weight: 600;
            color: #1a3a5c;
            margin-bottom: 15px;
            padding-bottom: 8px;
            border-bottom: 2px solid #1a3a5c;
        }
        .detail-row {
            display: flex;
            padding: 6px 0;
            .detail-label {
                font-weight: 600;
                color: #555;
                width: 140px;
                flex-shrink: 0;
            }
            .detail-value {
                color: #333;
            }
        }
    }
    .status-badge {
        &.active { color: #3c763d; font-weight: 600; }
        &.inactive { color: #a94442; font-weight: 600; }
    }
    .empty-state { padding: 30px 0; }
}

sp_widget.script:
(function() {
    data.accounts = [];
    data.isManager = gs.hasRole('x_274351_finance_0.manager');

    var gr = new GlideRecord('x_274351_finance_0_accounts');
    if (!data.isManager) {
        gr.addQuery('holder', gs.getUserID());
    }
    gr.orderBy('number');
    gr.query();
    while (gr.next()) {
        data.accounts.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number'),
            account_type: gr.getDisplayValue('account_type'),
            holder_name: gr.getDisplayValue('holder'),
            balance: parseFloat(gr.getValue('balance') || 0).toFixed(2),
            active: gr.getValue('active') == '1' || gr.getValue('active') == 'true'
        });
    }
})();
